/* Florida shoreline for the at-the-beach check (biteforecast.club).
   Data: GSHHG high-res coastline, clipped to Florida; main coasts simplified
   (max ~0.5 mi deviation), islands under 1.5 mi collapsed to centroids. */
/* true when (la,lo) is on water (ocean, bay, lagoon, inlet). */
function isLand(la, lo) {
  var i, j, r, x, y, inside, yi, xi, yj, xj, dLa, dLo;
  var c = Math.cos(la * Math.PI / 180);
  for (i = 0; i < FL_ISLES.length; i++) {
    dLa = (la - FL_ISLES[i][0]) * 69.0;
    dLo = (lo - FL_ISLES[i][1]) * c * 69.0;
    if (dLa * dLa + dLo * dLo < 0.5625) return true;
  }
  x = lo; y = la;
  for (i = 0; i < FL_RINGS.length; i++) {
    r = FL_RINGS[i]; inside = false;
    for (j = 0; j < r.length - 2; j += 2) {
      yi = r[j]; xi = r[j + 1]; yj = r[j + 2]; xj = r[j + 3];
      if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) inside = !inside;
    }
    if (inside) return true;
  }
  return false;
}
/* true when (lat,lon) is at/near fishable saltwater: on the water itself,
   or on land within 1.0 mi of a shoreline. */
function shoreOk(lat, lon) {
  return !isLand(lat, lon) || shoreDistMi(lat, lon) < 1.0;
}
/* Distance in miles from (la,lo) to the nearest shoreline (equirectangular). */
function shoreDistMi(la, lo) {
  var c = Math.cos(la * Math.PI / 180), best = 1e12, i, j, r, ax, ay, bx, by, dx, dy, t, ex, ey, dd, dLa, dLo;
  var px = lo * c * 69.0, py = la * 69.0;
  for (i = 0; i < FL_RINGS.length; i++) {
    r = FL_RINGS[i];
    for (j = 0; j < r.length - 2; j += 2) {
      ax = r[j + 1] * c * 69.0; ay = r[j] * 69.0;
      bx = r[j + 3] * c * 69.0; by = r[j + 2] * 69.0;
      dx = bx - ax; dy = by - ay;
      t = dx * dx + dy * dy;
      t = t ? ((px - ax) * dx + (py - ay) * dy) / t : 0;
      t = t < 0 ? 0 : t > 1 ? 1 : t;
      ex = ax + t * dx - px; ey = ay + t * dy - py;
      dd = ex * ex + ey * ey;
      if (dd < best) best = dd;
    }
  }
  for (i = 0; i < FL_ISLES.length; i++) {
    dLa = (py - FL_ISLES[i][0] * 69.0); dLo = (px - FL_ISLES[i][1] * c * 69.0);
    dd = dLa * dLa + dLo * dLo;
    if (dd < best) best = dd;
  }
  return Math.sqrt(best);
}
